using System;using System.IO;using System.Linq;using System.Threading.Tasks;using UnityEngine;using SkyIsland;using SkyIsland.Authority;
public static class AuthorityReview {
 sealed class MemoryStore:IAuthorityStore {public string data;public bool fail,ambiguous;public string Load()=>data;public void Commit(string json){if(fail)throw new IOException("injected pre-commit failure");data=json;if(ambiguous)throw new IOException("injected post-commit ambiguity");}}
 static AuthorityState Seed(int wood=30,int stone=20){var s=new AuthorityState();s.accounts.Add(new AccountState{id="acc_a",wood=wood,stone=stone});s.accounts.Add(new AccountState{id="acc_b",wood=30,stone=20});s.accounts.Add(new AccountState{id="acc_c",wood=30,stone=20});s.islands.Add(new IslandState{id="island_a",owner="acc_a",builders=new System.Collections.Generic.List<string>{"acc_b"},cells=new HexIsland().Snapshot(Vector3.zero).cells});return s;}
 static string Session(string token)=>token=="fixture-session-a"?"acc_a":token=="fixture-session-b"?"acc_b":token=="fixture-session-c"?"acc_c":null;
 static FoundationCommand Command(int revision=0,int q=2,int r=0)=>new FoundationCommand{requestId=Guid.NewGuid().ToString("D"),islandId="island_a",expectedRevision=revision,q=q,r=r};
 public static void Validate(){int n=0;Action<bool,string> check=(ok,name)=>{if(!ok)throw new Exception("AUTHORITY FAIL "+name);n++;};const string a="fixture-session-a",b="fixture-session-b",c="fixture-session-c";var memory=new MemoryStore();long now=100;var world=new FoundationAuthority(memory,Seed(),Session,()=>now);var cmd=Command();
  check(world.Place("acc_a",cmd).code=="UNAUTHENTICATED","account name cannot impersonate session");check(world.Place(c,cmd).code=="FORBIDDEN","uninvited account cannot build");check(world.Read(c,"island_a").code=="FORBIDDEN","uninvited account cannot read");check(world.Place(a,null).code=="INVALID_REQUEST","null command rejected");var invalid=Command();invalid.requestId="not-a-uuid";check(world.Place(a,invalid).code=="INVALID_REQUEST","bad id rejected");invalid=Command();invalid.foundationTypeId="free_admin_tile";check(world.Place(a,invalid).code=="INVALID_REQUEST","client cannot choose unpriced item");invalid=Command();invalid.q=int.MinValue;check(world.Place(a,invalid).code=="INVALID_REQUEST","coordinate overflow rejected");invalid=Command();invalid.expectedRevision=-1;check(world.Place(a,invalid).code=="INVALID_REQUEST","negative revision rejected");
  var ok=world.Place(a,cmd);check(ok.code=="OK"&&ok.wood==27&&ok.stone==18&&ok.revision==1&&ok.cellCount==8,"server places and debits once");check(world.Read(b,"island_a").wood==30,"collaborator stock isolated");ok.wood=999;check(world.Place(a,cmd).wood==27&&world.Read(a,"island_a").cellCount==8,"retry returns detached original result");var changed=JsonUtility.FromJson<FoundationCommand>(JsonUtility.ToJson(cmd));changed.q=3;check(world.Place(a,changed).code=="INVALID_REQUEST","same request id changed payload rejected");
  check(world.Place(b,Command()).code=="VERSION_CONFLICT","stale concurrent revision rejected");check(world.Place(b,Command(1,3,0)).code=="OK"&&world.Read(b,"island_a").wood==27&&world.Read(a,"island_a").wood==27,"shared island debits acting account");check(world.Place(a,Command(2,8,0)).code=="NOT_ADJACENT","floating foundation rejected");check(world.Place(a,Command(2,0,0)).code=="CELL_EXISTS","duplicate cell no debit");check(world.Read(a,"island_a").wood==27&&world.Read(a,"island_a").revision==2,"failure no stock or revision change");
  var restarted=new FoundationAuthority(memory,Seed(999,999),Session,()=>now);check(restarted.Place(a,cmd).code=="OK"&&restarted.Read(a,"island_a").wood==27,"restart restores data and original receipt");now+=FoundationAuthority.RetryWindowMs;check(restarted.Place(a,cmd).code=="REQUEST_EXPIRED"&&restarted.Read(a,"island_a").wood==27,"expired id never executes again");
  var poorStore=new MemoryStore();var poor=new FoundationAuthority(poorStore,Seed(2,1),Session);check(poor.Place(a,Command()).code=="INSUFFICIENT_MATERIALS"&&poor.Read(a,"island_a").wood==2,"server rejects insufficient materials");
  var failed=new MemoryStore();var fworld=new FoundationAuthority(failed,Seed(),Session);var pending=Command();failed.fail=true;check(fworld.Place(a,pending).code=="STORAGE_UNAVAILABLE","no success before durable commit");failed.fail=false;check(fworld.Place(a,pending).code=="STORAGE_UNAVAILABLE","faulted writer fenced until reload");fworld=new FoundationAuthority(failed,Seed(),Session);check(fworld.Read(a,"island_a").wood==30&&fworld.Place(a,pending).code=="OK","uncommitted retry recovers without lost stock");
  var ambiguous=new MemoryStore();var uncertain=new FoundationAuthority(ambiguous,Seed(),Session);var uncertainCmd=Command();ambiguous.ambiguous=true;check(uncertain.Place(a,uncertainCmd).code=="STORAGE_UNAVAILABLE","ambiguous commit never acknowledges");check(uncertain.Place(a,Command()).code=="STORAGE_UNAVAILABLE","ambiguous writer cannot overwrite committed state");ambiguous.ambiguous=false;uncertain=new FoundationAuthority(ambiguous,Seed(),Session);check(uncertain.Place(a,uncertainCmd).code=="OK"&&uncertain.Read(a,"island_a").wood==27,"ambiguous commit recovery replays once");
  var concurrent=new FoundationAuthority(new MemoryStore(),Seed(),Session);var parallel=Enumerable.Range(0,12).Select(i=>Task.Run(()=>concurrent.Place(i%2==0?a:b,Command()))).ToArray();Task.WaitAll(parallel);check(parallel.Count(t=>t.Result.code=="OK")==1&&parallel.Count(t=>t.Result.code=="VERSION_CONFLICT")==11,"competing same revision serializes");check(concurrent.Read(a,"island_a").wood+concurrent.Read(b,"island_a").wood==57,"concurrent debit exactly once");
  var repeated=new FoundationAuthority(new MemoryStore(),Seed(),Session);var repeatedCmd=Command();var repeats=Enumerable.Range(0,12).Select(i=>Task.Run(()=>repeated.Place(a,repeatedCmd))).ToArray();Task.WaitAll(repeats);check(repeats.All(t=>t.Result.code=="OK")&&repeated.Read(a,"island_a").wood==27,"simultaneous identical retries one debit");
  var full=Seed();full.islands[0].cells=Enumerable.Range(0,128).Select(i=>new Hex(i,0)).ToArray();var cap=new FoundationAuthority(new MemoryStore(),full,Session);check(cap.Place(a,Command(0,128,0)).code=="ISLAND_CAPACITY"&&cap.Read(a,"island_a").wood==30,"128 foundation cap preserved");
  string baseDir=Path.GetFullPath("../../ai/work/authority-tests"),dir=Path.Combine(baseDir,Guid.NewGuid().ToString("N")),file=Path.Combine(dir,"state.json");Directory.CreateDirectory(dir);
  try{using(var store=new FileAuthorityStore(file)){var disk=new FoundationAuthority(store,Seed(),Session);var diskCmd=Command();check(disk.Place(a,diskCmd).code=="OK","real file commit");bool blocked=false;try{using(var other=new FileAuthorityStore(file)){} }catch(IOException){blocked=true;}check(blocked,"OS file lease rejects second writer");var persisted=JsonUtility.FromJson<AuthorityState>(File.ReadAllText(file));check(persisted.accounts[0].wood==27&&persisted.receipts.Count==1,"stock and receipt in same persisted snapshot");}using(var store=new FileAuthorityStore(file)){var disk=new FoundationAuthority(store,Seed(),Session);check(disk.Read(a,"island_a").cellCount==8&&disk.Read(a,"island_a").wood==27,"real file reopen recovers");}File.WriteAllText(file,"broken");bool refused=false;try{using(var store=new FileAuthorityStore(file))new FoundationAuthority(store,Seed(),Session);}catch{refused=true;}check(refused&&File.ReadAllText(file)=="broken","corrupt store refuses startup without silent reset");}
  finally{string resolved=Path.GetFullPath(dir);if(resolved.StartsWith(baseDir+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))Directory.Delete(resolved,true);}
  Directory.CreateDirectory("../evidence/unity");File.WriteAllText("../evidence/unity/authority-tests.txt","PASS "+n+" authority/permission/two-account/concurrency/idempotency/version/durable-file/fault/restart assertions; UTC "+DateTime.UtcNow.ToString("o")+"\nSession resolver uses local fixture tokens. No Mirror transport, game scene integration, cloud, Android or network performance acceptance.");Debug.Log("SKY_AUTHORITY_TESTS_PASS "+n);
 }
}
